import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    friends = [0] * (n + 1)
    genders = [0] * (n + 1)
    for i in range(1, n + 1):
        friends[i] = int(input[2 * i - 1])
        genders[i] = int(input[2 * i])

    visited = [False] * (n + 1)
    pairs = []
    bg_pairs = 0

    def dfs(u, path):
        visited[u] = True
        path.append(u)
        v = friends[u]
        if visited[v]:
            cycle_start = path.index(v)
            cycle = path[cycle_start:]
            for i in range(0, len(cycle) - 1, 2):
                a, b = cycle[i], cycle[i + 1]
                pairs.append((a, b))
                if genders[a] != genders[b]:
                    nonlocal bg_pairs
                    bg_pairs += 1
        else:
            dfs(v, path)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, [])

    print(len(pairs), bg_pairs)
    for a, b in pairs:
        print(a, b)

if __name__ == "__main__":
    main()
